script=r'''
let currentAction='',incoming=false;
const sendCommand=(action,data={})=>parent.postMessage({type:'together-command',action,...data},'*');
const oldGo=go;go=(to,push=true)=>{if(to==='shelf'&&!S.privateUnlocked){sendCommand('unlock-shelf');return}if(route==='shelf'&&to!=='shelf')sendCommand('leave-shelf');oldGo(to,push)};
const originalRender=render;render=()=>{if(!incoming)return;originalRender()};
for(const [name,handler] of Object.entries(actions)){actions[name]=b=>{currentAction=name;handler(b)}}
document.addEventListener('submit',e=>{if(e.target.id==='editForm')currentAction='form:'+e.target.dataset.form},true);
actions.importFile=()=>{sendCommand('import-file');$('#sheet').close()};actions.importAudio=()=>{sendCommand('import-file');$('#sheet').close()};
actions.libraryOpen=b=>{if(b.dataset.kind==='file')sendCommand('open-file',{id:Number(b.dataset.id)});else if(b.dataset.kind==='note')noteEditor(S.notes.find(n=>n.id===Number(b.dataset.id)));else {recordClass=records.find(r=>r.id===Number(b.dataset.id))?.classId||recordClass;go('recordings')}};
actions.read=b=>sendCommand('read',{id:Number(b?.dataset?.id)||null});
actions.record=()=>sendCommand('record',{classId:recordClass,title:$('#audioTitle')?.value||'',notes:$('#audioNote')?.value||''});
actions.recordClass=b=>{recordClass=Number(b.dataset.id);sendCommand('record-class',{id:recordClass});render()};
actions.playAudio=b=>{const r=records.find(r=>r.id===Number(b.dataset.id));if(!r?.url){toast('This recording is not available on this device.');return}audioURLs[r.id]=r.url;playAudio(r)};
actions.deleteNote=b=>{sendCommand('delete-note',{id:Number(b.dataset.id)});$('#sheet').close()};
actions.archiveNote=b=>{sendCommand('archive-note',{id:Number(b.dataset.id)});$('#sheet').close()};
actions.archiveInbox=b=>sendCommand('archive-inbox',{id:Number(b.dataset.id)});
actions.restore=b=>sendCommand('restore',{id:Number(b.dataset.id)});
actions.moveToNotes=b=>sendCommand('inbox-to-note',{id:Number(b.dataset.id)});
actions.deleteTask=b=>{sendCommand('delete-task',{id:Number(b.dataset.id)});$('#sheet').close()};
actions.deleteEvent=b=>{sendCommand('delete-event',{id:Number(b.dataset.id)});$('#sheet').close()};
actions.course=b=>sendCommand('course',{id:Number(b.dataset.id)});
actions.homeDay=b=>{selected=b.dataset.value;year=date(selected).getFullYear();month=date(selected).getMonth();go('calendar')};
actions.calToday=()=>{year=date(TODAY).getFullYear();month=date(TODAY).getMonth();selected=TODAY;render()};
actions.classGuide=()=>sheet('Keep close to this class.',`<div class="stack">${S.files.map(f=>`<button class="itemrow" data-action="libraryOpen" data-kind="file" data-id="${f.id}">${soft('file')}<div><strong>${esc(f.title)}</strong><small>${esc(f.type)}</small></div>${ic('chev')}</button>`).join('')||empty('Add a reference file in your Library.','file')}</div>`);
actions.about=()=>sheet('A little life, together.',`<p style="font:22px/1.7 Georgia,serif">One atmosphere.<br>Many little parts of your day.</p><p class="small">Your plans, routines, journals, books and class notes, using the real records saved in aérea.</p>`);
actions.allThemes=()=>sheet('Your atmospheres.',`<div class="stack">${(S.themeOptions||[]).map(t=>`<button class="itemrow" data-action="appTheme" data-value="${esc(t.id)}"><strong>${esc(t.name)}</strong>${ic('chev')}</button>`).join('')}</div>`);
actions.appTheme=b=>sendCommand('app-theme',{id:b.dataset.value});
const oldSettings=settingsView;settingsView=()=>oldSettings()+`<section class="section">${section('More atmospheres')}<button class="itemrow" data-action="allThemes">${soft('spark')}<div><strong>All app themes</strong><small>Choose another little world.</small></div>${ic('chev')}</button></section>`;
function miniWeek(context='home'){const start=date(TODAY);start.setDate(start.getDate()-start.getDay());return `<div class="week">${DAYS.map((d,i)=>{const v=new Date(start);v.setDate(v.getDate()+i);const k=dateKey(v.getFullYear(),v.getMonth(),v.getDate());return `<button class="${(context==='study'?weekDay===i:k===TODAY)?'active':''}" ${context==='study'?`data-action="weekDay" data-id="${i}"`:`data-action="homeDay" data-value="${k}"`}><small>${d.toUpperCase()}</small><span>${v.getDate()}</span><i></i></button>`}).join('')}</div>`}
due=r=>r.scheduled?.[TODAY]!==null&&r.scheduled?.[TODAY]!==undefined;
function continueReading(){const f=[...S.files].filter(f=>['PDF','EPUB'].includes(f.type)&&f.lastOpenedAt).sort((a,b)=>b.lastOpenedAt.localeCompare(a.lastOpenedAt))[0];if(!f)return '';return `<button class="hero readingcard wide" data-action="read" data-id="${f.id}"><div class="cover">${esc(f.title.replace(/\.(pdf|epub)$/i,''))}</div><div class="body"><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h3>${esc(f.title)}</h3><div class="small">${esc(f.meta)}</div><div class="progress" style="margin-top:15px"><i style="width:${Math.round((f.percentage||0)*100)}%"></i></div></div></button>`}
const originalLibrary=libraryView;libraryView=()=>{let html=originalLibrary();return html.replace(/<button class="hero readingcard wide" data-action="read">[\s\S]*?<\/button>/,continueReading())};
const originalToday=views.today;views.today=()=>{let html=originalToday();const names=S.classes.filter(c=>c.days.includes(date(TODAY).getDay())).map(c=>c.title);html=html.replace('Sunday</span>',esc(date(TODAY).toLocaleDateString('en-US',{weekday:'long'}))+'</span>').replace('A slower kind of Sunday.','A little room for today.').replace('No classes today. Keep a little space for yourself.',names.length?esc(names.join(' · ')):'No classes today. Keep a little space for yourself.');return html.replace(/<button class="card readingcard" data-action="read">[\s\S]*?<\/button>/,continueReading())};
function careRhythm(){const start=TODAY.slice(0,8)+'01';const total=Object.values(S.routines.reduce((acc,r)=>{for(const [day,value]of Object.entries(r.scheduled||{}))if(day>=start&&day<=TODAY&&value!==null){acc.total++;if(value)acc.done++}return acc},{done:0,total:0}));const done=total[0],count=total[1],p=count?Math.round(done/count*100):0;const week=date(TODAY);week.setDate(week.getDate()-week.getDay()-7);const days=Array.from({length:7},(_,i)=>{const v=new Date(week);v.setDate(v.getDate()+i);return dateKey(v.getFullYear(),v.getMonth(),v.getDate())});const history=days.map(day=>{let n=0,d=0;for(const r of S.routines){if(r.scheduled?.[day]!==null&&r.scheduled?.[day]!==undefined){n++;if(r.scheduled[day])d++}}return n?Math.round(d/n*100):0});return `<div class="card cluster" style="gap:25px"><div class="ring" style="--p:${p}"><div><b>${p}%</b><small>completed</small></div></div><div><span class="eyebrow">YOUR LITTLE STEPS</span><h3 style="margin-top:9px">A little care adds up.</h3><p class="small">${done} of ${count} scheduled steps<br>this month so far.</p></div></div><section class="section">${section('A week of little steps')}<div class="card"><div class="row"><span class="small">Last complete week</span><span class="tiny">${labelDate(days[0])}–${labelDate(days[6])}</span></div><div class="bars">${history.map((p,i)=>`<div class="barcol"><span>${p}%</span><div class="bar" style="--h:${p}%"><i></i></div><span>${DAYS[i][0]}</span></div>`).join('')}</div></div></section><section class="section">${section('A gentler way to keep going')}<div class="hero"><h2 style="font-size:25px">Every return counts.</h2><p>Only scheduled routines count towards your rhythm. Rest days have a place here, too.</p><button class="link" style="margin-top:18px" data-action="careToday">Back to your care ↗</button></div></section>`}
function degreeView(){let done=S.courseDone.length,p=courses.length?Math.round(done/courses.length*100):0,terms=[...new Set((S.courses||[]).map(c=>c.quarter))];return head('STUDY · LITTLE BY LITTLE','My degree','Every subject is a step. Every step counts.')+`<div class="card cluster" style="gap:25px"><div class="ring" style="--p:${p}"><div><b>${p}%</b><small>completed</small></div></div><div><h3 style="font-size:15px">A little closer.</h3><p class="small">${done} of ${courses.length} courses completed</p></div></div><nav class="tabs" style="margin-top:30px"><button class="active">Your plan</button><button data-nav="schedule">Weekly schedule ↗</button></nav><div class="stack">${terms.map(term=>`<details class="card"><summary style="cursor:pointer;font-size:13px;list-style:none"><div class="row"><div>Term ${term}<div class="tiny" style="margin-top:5px">${S.courses.filter(c=>c.quarter===term&&S.courseDone.includes(c.id)).length} completed</div></div><span class="muted">⌄</span></div></summary><div class="stack" style="margin-top:22px">${S.courses.filter(c=>c.quarter===term).map(c=>`<div class="cluster" style="gap:12px;padding:9px 0"><button class="check" data-action="course" data-id="${c.id}" aria-label="Mark ${esc(c.name)} complete" aria-pressed="${S.courseDone.includes(c.id)}">${S.courseDone.includes(c.id)?ic('check'):''}</button><span style="font-size:11px">${esc(c.name)}</span></div>`).join('')}</div></details>`).join('')}</div>`}
const originalRecordings=recordingsView;recordingsView=()=>S.classes.length?originalRecordings():head('CLASS LIBRARY','Recordings & notes','Every class, a little easier to come back to.')+empty('Add a class to keep its recordings and notes together.','mic')+`<button class="secondary wide" data-action="newClass">${ic('plus')} Add class</button>`;
const originalStudy=studyView;studyView=()=>originalStudy().replace(/NOVEMBER \d+/g,date(TODAY).toLocaleDateString('en-US',{month:'long',day:'numeric'}).toUpperCase());
function shelfRows(items){return items.map(s=>`<article class="card shelfcard ${s.type==='Series'?'series':''}"><div class="row"><span class="eyebrow">${s.type.toUpperCase()} · ${esc(s.fandom)}</span><span class="badge ${s.status==='Complete'?'sage':'honey'}">${s.status==='Complete'?'Complete ✓':'In progress'}</span></div><h2>${esc(s.title)}</h2><div class="small">by <span style="color:var(--accent)">${esc(s.author)}</span></div><div class="small" style="margin-top:16px">${s.works?.length?`${s.works.length} works`:esc(s.chapters||'')} · ${s.words.toLocaleString()} words</div><div class="small" style="margin-top:21px;color:var(--sage)">${esc(s.ship)}</div><p class="synopsis">${esc(s.text)}</p><div class="tags">${(tagMore?s.tags:s.tags.slice(0,4)).map(t=>`<button class="tag" data-action="tagSearch" data-value="${esc(t)}">${esc(t)}</button>`).join('')}${s.tags.length>4?`<button class="link" data-action="moreTags">${tagMore?'Fewer tags':'+'+(s.tags.length-4)+' tags'}</button>`:''}</div><div class="shelffoot"><div><button class="primary" data-action="read" data-id="${s.id}">${ic('book')} ${s.download?'Read EPUB':'Download EPUB'}</button><div class="tiny" style="margin-top:8px">${s.download?'↓ Downloaded':''}</div></div>${s.url?`<a class="link" target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">Open on AO3 ↗</a>`:''}</div>${s.works?.length?`<details style="padding-top:24px"><summary class="link">Explore all ${s.works.length} works</summary>${s.works.map((w,i)=>`<button class="work" data-action="read" data-id="${w.id}"><span>${i+1}</span><div><strong>${esc(w.title)}</strong><small class="tiny">${w.words.toLocaleString()} words</small></div></button>`).join('')}</details>`:''}</article>`).join('')||empty('No stories found. Try changing a filter.','book')}
const originalShelf=shelfView;shelfView=()=>originalShelf().replace(/<div class="miniStats">[\s\S]*?<\/div>/,`<div class="miniStats"><b>${stories.length}</b> shelf cards<span>·</span><b>${stories.filter(s=>s.type==='Series').length}</b> series<span>·</span><b>${stories.filter(s=>s.download).length}</b> downloaded</div>`);
$('.demofooter')?.remove();
window.addEventListener('message',e=>{if(e.source!==parent)return;const data=e.data;if(data?.type==='together-state'){const wasPrivate=S.privateUnlocked;S=data.state;TODAY=S.today;records=S.records||[];stories=S.stories||[];courses=(S.courses||[]).map(c=>c.name);audioURLs=Object.fromEntries(records.filter(r=>r.url).map(r=>[r.id,r.url]));recording=!!S.isRecording;recordElapsed=(S.recordingSeconds||0)*1000;if(!incoming){year=date(TODAY).getFullYear();month=date(TODAY).getMonth();selected=TODAY;weekDay=date(TODAY).getDay();recordClass=S.classes[0]?.id||0;route=S.simple?'calendar':'today'}incoming=true;if(!wasPrivate&&S.privateUnlocked){route='shelf'}if($('#sheet').open||document.activeElement?.matches('input,textarea')){applyTheme();if($('#recordTimer'))$('#recordTimer').textContent=duration(recordElapsed/1000);return}render()}if(data?.type==='together-back'){if(!$('#reader').classList.contains('hidden')){if($('#reader').classList.contains('focus'))$('#reader').classList.remove('focus');else $('#reader').classList.add('hidden')}else if($('#sheet').open)$('#sheet').close();else if(historyRoutes.length)go(historyRoutes.pop(),false);else if(route!=='today')go('today',false);else sendCommand('exit')}if(data?.type==='together-error')toast(data.message)});
parent.postMessage({type:'together-ready'},'*');
'''
h=h.replace("${r.days.length===7?'Every day':r.days.map(d=>DAYS[d]).join(' · ')}", "${r.cadenceLabel||(r.days.length===7?'Every day':r.days.map(d=>DAYS[d]).join(' · '))}")
h=h.replace("r?.time==='9:00 PM'?'21:00':r?.time==='8:30 PM'?'20:30':'09:00'","r?.rawTime||'09:00'")
script=script.replace("$('.demofooter')?.remove();","$('.demofooter')?.remove();$('#view').replaceChildren();")
