script+="document.addEventListener('submit',e=>{if(e.target.id==='editForm'&&e.target.dataset.form==='class'&&new FormData(e.target).getAll('days').includes('0')){e.preventDefault();e.stopImmediatePropagation();toast('Choose a class day from Monday to Saturday.')}},true);\n"
h=h.replace("['Personal','University','Health'],e?.category","[...new Set(['Personal','University','Health',...S.events.map(e=>e.category)])],e?.category")
h=h.replace("function labelDate(s,opts={month:'long',day:'numeric'}){return", "function labelDate(s,opts={month:'long',day:'numeric'}){if(!s||!Number.isFinite(date(s).getTime()))return 'Not set';return")
h=h.replace('What you can explore in the prototype','Your app, connected.')
h=h.replace('</script>',script+'</script>')
